export const TOOL_HELP = {
	recab: "A/B slot + boot-selection manager\n\nUsage: recab <COMMAND>\n\nCommands:\n  status    Show detected A/B status\n  stage     Write a prebuilt system into the inactive slot (formats the slot)\n  set-next  Stage a one-shot trial boot for a slot\n  commit    Commit currently booted slot as known-good and default\n  rollback  Configure next boot to previously known-good slot\n  help      Print this message or the help of the given subcommand(s)\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version",
	recinit: "Rootless initramfs builder for Linux\n\nUsage: recinit [OPTIONS] <COMMAND>\n\nCommands:\n  build-tiny     Build a tiny initramfs for live ISO boot\n  build-install  Build an install initramfs for booting from disk\n  modules        List available module presets\n  help           Print this message or the help of the given subcommand(s)\n\nOptions:\n  -q, --quiet    Quiet mode (suppress progress messages)\n  -h, --help     Print help\n  -V, --version  Print version",
	reciso: "Create bootable UEFI ISOs from kernel + initramfs + rootfs\n\nUsage: reciso [OPTIONS] --kernel <KERNEL> --initrd <INITRD> --rootfs <ROOTFS> --label <LABEL> --output <OUTPUT>\n\nOptions:\n  -k, --kernel <KERNEL>\n          Path to kernel image (vmlinuz)\n\n  -i, --initrd <INITRD>\n          Path to initramfs image\n\n  -r, --rootfs <ROOTFS>\n          Path to rootfs image (EROFS)\n\n  -l, --label <LABEL>\n          ISO volume label\n\n  -o, --output <OUTPUT>\n          Output ISO path\n\n      --uki <UKIS>\n          Prebuilt UKI files to include (can be specified multiple times)\n\n      --build-uki <BUILD_UKIS>\n          Build UKIs inline. Format: \"name:extra_cmdline:filename\" Example: \"Emergency:emergency:myos-emergency.efi\"\n\n      --extra-file <EXTRA_FILES>\n          Add an extra file to the ISO. Format: \"src:dst\" Example: \"/tmp/initramfs-installed.img:boot/initramfs-installed.img\"\n\n      --overlay-image <OVERLAY_IMAGE>\n          Live overlay payload image (EROFS) to include\n\n      --os-name <OS_NAME>\n          OS name for the boot menu (e.g., \"LevitateOS\")\n\n      --os-id <OS_ID>\n          OS identifier (e.g., \"levitateos\")\n\n      --os-version <OS_VERSION>\n          OS version (e.g., \"1.0\")\n\n      --no-checksum\n          Skip checksum generation\n\n      --live-payload-layout <LAYOUT>\n          Layout for live payloads (`iso-files` or `appended-partitions`)\n\n          Possible values:\n          - iso-files:           Keep payloads as files under `live/` in ISO filesystem\n          - appended-partitions: Append payload images as GPT partitions (direct block mounts in initramfs)\n          \n          [default: appended-partitions]\n\n      --systemd-boot <SYSTEMD_BOOT>\n          systemd-boot UEFI binary (default: the build host's)\n          \n          [default: /usr/lib/systemd/boot/efi/systemd-bootx64.efi]\n\n  -q, --quiet\n          Quiet mode - only print errors\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version\n\nEXAMPLES:\n    # Basic ISO with auto-generated UKI\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO -o output.iso\n\n    # With prebuilt UKIs\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --uki myos-live.efi --uki myos-emergency.efi -o output.iso\n\n    # Build UKIs inline (format: name:extra_cmdline:filename)\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --build-uki 'Normal::myos.efi' --build-uki 'Emergency:emergency:myos-emergency.efi' --os-name MyOS --os-id myos --os-version 1.0 -o output.iso\n\n    # With live overlay image (EROFS)\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --overlay-image live-overlay.erofs -o output.iso\n\nREQUIREMENTS:\n    - systemd-boot (dnf install systemd-boot)\n    - xorriso (dnf install xorriso)\n    - mtools (dnf install mtools)\n    - ukify (dnf install systemd-ukify) - if building UKIs",
	recpart: "Mode-aware partition planning and apply backend\n\nUsage: recpart [OPTIONS] <COMMAND>\n\nCommands:\n  list-disks  Enumerate candidate target disks\n  plan        Generate a deterministic partition plan\n  apply       Apply a partition plan directly to disk\n  help        Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json     Emit machine-readable JSON (errors too, on stderr)\n  -h, --help     Print help\n  -V, --version  Print version",
	recstrap: "Extracts the LevitateOS EROFS rootfs image to a target directory. This is the pacstrap equivalent for LevitateOS - it only extracts files; the live install docs describe the rest of the installation.\n\nUsage: recstrap [OPTIONS] <TARGET>\n\nArguments:\n  <TARGET>\n          Target directory (must be mounted, e.g., /mnt)\n\nOptions:\n      --rootfs <ROOTFS>\n          Rootfs image (auto-detected on the live ISO if not specified)\n\n  -f, --force\n          Shorthand for --allow-non-mountpoint --allow-nonempty\n\n      --allow-non-mountpoint\n          Allow a target directory that is not a mount point\n\n      --allow-nonempty\n          Allow a target directory that already contains files\n\n      --allow-host-root-fs\n          Allow extracting onto the filesystem that holds the running system's / (never implied by --force)\n\n  -q, --quiet\n          Quiet mode - minimal output for scripting\n\n  -c, --check\n          Check mode - run pre-flight validation only, don't extract\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version",
	recchroot: "Enter chroot with proper bind mounts (like arch-chroot)\n\nUsage: recchroot <CHROOT_DIR> [COMMAND]...\n\nArguments:\n  <CHROOT_DIR>  Chroot directory (e.g., /mnt)\n  [COMMAND]...  Command to run (default: root's login shell in the target)\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version",
	recfstab: "Reads mounted filesystems under a root directory and outputs fstab entries with UUIDs (or LABELs/PARTUUIDs/PARTLABELs). Designed for system installation workflows where you need to generate /etc/fstab for a newly installed system.\n\nUsage: recfstab [OPTIONS] <ROOT>\n\nArguments:\n  <ROOT>\n          Root directory to scan for mounted filesystems (e.g., /mnt)\n\nOptions:\n  -L, --label\n          Use filesystem LABEL instead of UUID for device identification\n\n  -p, --partuuid\n          Use partition UUID (PARTUUID) instead of filesystem UUID\n\n  -t, --partlabel\n          Use partition LABEL (PARTLABEL) instead of filesystem UUID\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version",
	recuki: "Build Unified Kernel Images (UKI) from kernel + initramfs + cmdline\n\nUsage: recuki [OPTIONS] --kernel <KERNEL> --initrd <INITRD> --cmdline <CMDLINE> --output <OUTPUT>\n\nOptions:\n  -k, --kernel <KERNEL>          Path to kernel image (vmlinuz)\n  -i, --initrd <INITRD>          Path to initramfs image\n  -c, --cmdline <CMDLINE>        Kernel command line\n  -o, --output <OUTPUT>          Output path for the .efi file\n      --os-name <OS_NAME>        OS name for the boot menu (e.g., \"LevitateOS\")\n      --os-id <OS_ID>            OS identifier (e.g., \"levitateos\")\n      --os-version <OS_VERSION>  OS version (e.g., \"1.0\")\n  -q, --quiet                    Quiet mode - only print errors\n  -h, --help                     Print help\n  -V, --version                  Print version\n\nEXAMPLES:\n    # Basic UKI\n    recuki -k vmlinuz -i initramfs.img -c 'root=LABEL=root rw' -o boot.efi\n\n    # With OS branding (shows in boot menu)\n    recuki -k vmlinuz -i initramfs.img -c 'root=LABEL=root rw' \\\n           --os-name 'LevitateOS' --os-id levitateos --os-version '1.0' \\\n           -o levitateos.efi\n\nREQUIREMENTS:\n    Requires 'ukify' from systemd.",
} as const
